"""Memory API routes."""

from fastapi import APIRouter, Query
from fastapi.responses import JSONResponse

from backend.api.errors import ServiceUnavailableError
from backend.config import get_settings
from backend.pipeline.memory.models import MemoryQuery, MemoryType

router = APIRouter()


@router.get("/recall")
async def recall_memories(
    query: str,
    memory_type: MemoryType | None = None,
    top_k: int = Query(default=10, ge=1, le=100),
):
    """Query the agent memory system."""
    settings = get_settings()
    if not settings.memory_enabled:
        raise ServiceUnavailableError("Memory system is disabled")

    from backend.pipeline.memory.service import MemoryService

    memory = MemoryService(settings.memory_persist_dir)
    results = await memory.recall(
        MemoryQuery(
            query=query,
            memory_type=memory_type,
            top_k=top_k,
        )
    )
    return {
        "query": query,
        "results": [
            {
                "content": r.content[:200],
                "type": r.memory_type.value,
                "confidence": r.truth.confidence,
                "created_at": str(r.created_at),
            }
            for r in results
        ],
    }


@router.get("/stats")
async def memory_stats():
    """Get memory system statistics."""
    settings = get_settings()
    if not settings.memory_enabled:
        raise ServiceUnavailableError("Memory system is disabled")

    from backend.pipeline.memory.service import MemoryService

    memory = MemoryService(settings.memory_persist_dir)
    all_entries = list(memory._index.values())
    return {
        "total_memories": len(all_entries),
        "by_type": {
            mt.value: sum(1 for e in all_entries if e.memory_type == mt) for mt in MemoryType
        },
    }


@router.delete("/{entry_id}")
async def delete_memory(entry_id: str):
    """Delete a memory entry by ID."""
    settings = get_settings()
    if not settings.memory_enabled:
        raise ServiceUnavailableError("Memory system is disabled")

    from backend.pipeline.memory.service import MemoryService

    memory = MemoryService(settings.memory_persist_dir)
    deleted = await memory.delete(entry_id)
    if not deleted:
        return JSONResponse(status_code=404, content={"error": "Memory entry not found"})
    return {"status": "deleted", "entry_id": entry_id}

"""Governance approval API routes."""

from fastapi import APIRouter, HTTPException
from pydantic import BaseModel

router = APIRouter()


class DenyRequest(BaseModel):
    amendment: str | None = None


# Module-level reference to the approval manager, set during app startup.
_approval_manager = None


def set_approval_manager(manager) -> None:
    global _approval_manager
    _approval_manager = manager


def _get_manager():
    if _approval_manager is None:
        raise HTTPException(status_code=503, detail="Governance not initialized")
    return _approval_manager


@router.get("/pending")
async def list_pending_approvals():
    """List all pending governance approvals."""
    manager = _get_manager()
    return {"pending": manager.get_pending()}


@router.post("/{decision_id}/approve")
async def approve_decision(decision_id: str):
    """Approve a pending governance decision."""
    manager = _get_manager()
    if not manager.approve(decision_id):
        raise HTTPException(status_code=404, detail=f"No pending approval '{decision_id}'")
    return {"status": "approved", "decision_id": decision_id}


@router.post("/{decision_id}/deny")
async def deny_decision(decision_id: str, body: DenyRequest | None = None):
    """Deny a pending governance decision."""
    manager = _get_manager()
    amendment = body.amendment if body else None
    if not manager.deny(decision_id, amendment=amendment):
        raise HTTPException(status_code=404, detail=f"No pending approval '{decision_id}'")
    return {"status": "denied", "decision_id": decision_id, "amendment": amendment}

"""Cost tracking API routes."""

from pathlib import Path

from fastapi import APIRouter, HTTPException

from backend.providers.provider_factory import get_registry

router = APIRouter()


def _tracker():
    return get_registry().cost_tracker


@router.get("/summary")
async def cost_summary():
    """Total cost summary across all recorded events."""
    return _tracker().summary()


@router.get("/by-provider")
async def cost_by_provider():
    """Cost breakdown by provider."""
    return _tracker().by_provider()


@router.get("/by-stage")
async def cost_by_stage():
    """Cost breakdown by pipeline stage."""
    return _tracker().by_stage()


@router.get("/by-model")
async def cost_by_model():
    """Cost breakdown by provider/model."""
    return _tracker().by_model()


@router.get("/run/{run_id}")
async def cost_for_run(run_id: str):
    """Load persisted cost events for a specific run."""
    from backend.config import get_settings

    settings = get_settings()
    path = Path(f"{settings.cost_persist_dir}/{run_id}.jsonl")
    if not path.exists():
        raise HTTPException(status_code=404, detail=f"No cost data for run {run_id}")

    from backend.providers.provider_factory import CostTracker

    tracker = CostTracker.load(str(path))
    return {
        "run_id": run_id,
        "summary": tracker.summary(),
        "by_provider": tracker.by_provider(),
        "by_stage": tracker.by_stage(),
    }

